insert into public.practices (id, tool, category, name, details, frequency, priority, how_to, active, sort_order) values
  ('cs1', 'CrowdStrike', 'Alert Triage', 'Triage all new Falcon detections/incidents', 'Review the Endpoint Detections / Incidents queue (or unified Alerts). Assign each detection, set status (In Progress / True Positive / False Positive), and document the verdict. Prioritize Critical/High severity and anything Falcon OverWatch flags.', 'Continuous', 'Critical', 'Menu (☰) > Endpoint security > Monitor > Endpoint detections > Status filter = New > click a detection to open the side panel > Edit status (In progress/Closed) and assign it to yourself', true, 1),
  ('cs2', 'CrowdStrike', 'Alert Triage', 'Investigate the full process tree before closing a detection', 'Open the process tree / graph for each detection. Check the parent/child chain, command line, network connections, file writes, and hashes. Pivot on the hash and host to see if the activity occurs elsewhere.', 'Continuous', 'High', 'Menu (☰) > Endpoint security > Monitor > Endpoint detections > click the detection > See full detection (button at the bottom of the side panel) > Process tree tab. The Process graph and Events timeline tabs are next to it.', true, 2),
  ('cs3', 'CrowdStrike', 'Sensor Health', 'Find hosts with stale or missing sensors', 'In Host Management, filter for hosts not seen in more than 7 days and sensors in Reduced Functionality Mode (RFM). Compare the sensor host count against the AD/Intune/asset inventory to find unprotected machines.', 'Weekly', 'High', 'Menu (☰) > Host setup and management > Manage endpoints > Host management > Hosts tab > Add filters > Last seen (or sort the Last seen column oldest-first). The Sensor version column is on the same page if you need to spot outdated sensors.', true, 3),
  ('cs4', 'CrowdStrike', 'Configuration', 'Review exclusions (ML, IOA, Sensor Visibility)', 'Export every exclusion. Each one should have a ticket and business owner, and its scope should be as narrow as possible. Sensor Visibility exclusions are the riskiest; remove any that are no longer needed.', 'Quarterly', 'High', 'Menu (☰) > Endpoint security > Configure > Exclusions > check each tab: Machine learning (file path), Machine learning (certificate), IOA, Sensor visibility, and Application abuse. Use "See audit log" on that page to see who changed what.', true, 4),
  ('cs5', 'CrowdStrike', 'Threat Hunting', 'Hunt with Event Search / Advanced Event Search', 'Run saved hunting queries for things like encoded PowerShell, LOLBins (certutil, mshta, rundll32), new services, or RMM tools that aren''t approved at SHU. Record the queries and results.', 'Weekly', 'Medium', 'N/A – no Event Search page for our account. In a detection, Investigate > Investigate event / host / hash all show a padlock.', false, 5),
  ('cs6', 'CrowdStrike', 'Threat Intel', 'Maintain custom IOCs', 'Add hashes and domains from confirmed incidents and trusted intel (e.g., REN-ISAC, CISA) to IOC Management with the right action and an expiration date. Remove expired or noisy IOCs.', 'Weekly', 'Medium', 'Menu (☰) > Endpoint security > Configure > IOC management > filter by Indicator type, Action, or Expiration date > review and update entries', true, 6),
  ('cs7', 'CrowdStrike', 'Vulnerability', 'Review Spotlight exposure (if licensed)', 'Review critical and exploited (CISA KEV) vulnerabilities found by Falcon Spotlight. Send remediation tickets to the system owners.', 'Weekly', 'Medium', 'N/A – Spotlight isn''t licensed. There''s no Vulnerability/Exposure page in the menu or in Falcon search, only documentation.', false, 7),
  ('cs8', 'CrowdStrike', 'Device Control', 'Review USB / Device Control events', 'Review blocked and allowed USB mass-storage events, especially on systems that handle sensitive data (Registrar, Finance, HR).', 'Weekly', 'Low', 'N/A – Device Control isn''t licensed. There''s no Device Control policy page in the menu or in Falcon search, only documentation.', false, 8),
  ('md1', 'Microsoft Defender', 'Alert Triage', 'Triage the Defender XDR incident queue', 'In security.microsoft.com, work the Incidents queue. Assign an owner, set a classification (True Positive / False Positive / Informational), and resolve it with notes. Look at incidents that correlate across email, identity, and endpoint first.', 'Continuous', 'Critical', 'Investigation & response > Incidents & alerts > Incidents > sort by Priority score (the queue''s default filter is Priority score 15–100) > open an incident > set Status/Classification and assign it to yourself.', true, 9),
  ('md2', 'Microsoft Defender', 'Email Security', 'Triage user-reported phishing (Submissions)', 'Review Submissions > User reported. Check the verdict, then use Threat Explorer to find and purge similar messages across all mailboxes. Coordinate with Abnormal so the work isn''t duplicated.', 'Daily', 'High', 'Investigation & response > Actions & submissions > Submissions > User reported tab > select a message > Mark as and notify (or Submit to Microsoft for analysis)', true, 10),
  ('md3', 'Microsoft Defender', 'Email Security', 'Review quarantine release requests', 'Review admin quarantine and release requests. Never release high-confidence phish or malware. Write down why each release was approved.', 'Daily', 'Medium', 'Email & collaboration > Review > Quarantine > Email tab > Filter > Release status = Release requested > select a message > Release or Deny', true, 11),
  ('md4', 'Microsoft Defender', 'Email Security', 'Audit tenant allow/block lists and policy exceptions', 'Review the Tenant Allow/Block List, transport rules that bypass filtering, and Safe Links/Safe Attachments exceptions. Remove stale or overly broad entries, such as allow-listed whole domains.', 'Monthly', 'High', 'Email & collaboration > Policies & rules > Threat policies > Tenant Allow/Block Lists > check each tab: Domains & addresses, Spoofed senders, URLs, Files, IP addresses, and Teams senders. Sort by "Remove on" and "Last used date" to find stale entries. There are about 6,500 entries, and many are set to "Never expire."', true, 12),
  ('md5', 'Microsoft Defender', 'Identity', 'Review risky users and risky sign-ins (Entra ID Protection)', 'Review High and Medium risk users and sign-ins (impossible travel, unfamiliar sign-in properties, leaked credentials). Confirm or dismiss each one, and require a password reset and session revocation when compromise is confirmed.', 'Daily', 'Critical', 'Assets > Identities > Human Identities tab > filter Risk score (the Risky Identities count is shown at the top). Risky sign-ins themselves are in the Entra admin center: Protection > Identity Protection > Risky sign-ins. I tried to open Entra to confirm that path, but the tab didn''t load, so double-check it.', true, 13),
  ('md6', 'Microsoft Defender', 'Identity', 'Monitor mailbox rule and OAuth app abuse', 'Alert on new inbox forwarding or delete rules and on OAuth apps that get high-privilege consent. Both are common signs that a student or staff account has been taken over.', 'Daily', 'High', 'OAuth: Cloud apps > OAuth apps (App governance is right below it). Mailbox rules: Cloud apps > Activity log > filter Activity type = New-InboxRule / Set-InboxRule. You can also run that as an Advanced hunting query against CloudAppEvents.', true, 14),
  ('md7', 'Microsoft Defender', 'Threat Hunting', 'Run Advanced Hunting (KQL) queries', 'Keep a library of KQL hunts (e.g., EmailEvents with clicked URLs, IdentityLogonEvents anomalies, DeviceProcessEvents). Turn useful hunts into custom detection rules.', 'Weekly', 'Medium', 'Investigation & response > Hunting > Advanced hunting (there''s also a shortcut in the left icon bar). Saved and scheduled queries live under Hunting > Custom detection rules.', true, 15),
  ('md8', 'Microsoft Defender', 'Posture', 'Track Microsoft Secure Score', 'Review Secure Score trends and recommended actions. Raise the top improvements with IT leadership and record score changes month over month.', 'Monthly', 'Medium', 'Exposure management > Secure score > Recommended actions tab', true, 16),
  ('md9', 'Microsoft Defender', 'Training', 'Run Attack Simulation Training campaigns (if licensed)', 'Run phishing simulations for faculty, staff, and student workers. Track click and report rates and assign training to repeat clickers.', 'Quarterly', 'Low', 'Email & collaboration > Attack simulation training > Simulations tab > Launch a simulation. Use the Reports and Training tabs to check results. This one is licensed: there are already simulations like "SEPT 2026 STUDENT TEST," and only 50% of users have been simulated so far.', true, 17),
  ('sp1', 'Splunk', 'Detection Engineering', 'Tune noisy correlation searches', 'Review alert volume and false-positive rate for each search. Tune thresholds and allow-lists, and retire searches that never produce useful alerts. Document every change.', 'Monthly', 'Medium', 'Settings (gear icon) > Knowledge > Searches, reports, and alerts > set Owner = All and Type = Alerts > sort by the Alerts column to find the noisiest ones > Edit > Edit Search to tighten the SPL or add throttling. For the actual hits, go to Activity (pulse icon) > Triggered Alerts.', true, 18),
  ('sp2', 'Splunk', 'Platform Health', 'Monitor skipped/failed scheduled searches', 'Check for skipped or deferred searches (index=_internal sourcetype=scheduler status=skipped). A skipped detection search means a missed alert.', 'Weekly', 'High', 'Activity (pulse icon) > Jobs > Owner = All owners > Status filter = Failed.', true, 19),
  ('sp3', 'Splunk', 'Reporting', 'Maintain SOC dashboards and metrics', 'Keep dashboards for alert volume by tool, MTTD/MTTR, top targeted users, and source health. Review them at the weekly SOC meeting.', 'Weekly', 'Low', 'Dashboards (left sidebar) > filter or search the list > Edit to update a dashboard, or Create New Dashboard. There are currently 22 dashboards in Search & Reporting, mostly Classic and some Dashboard Studio.', true, 20),
  ('ab1', 'Abnormal', 'Alert Triage', 'Review the Threat Log and auto-remediated messages', 'Review attacks Abnormal detected and remediated (BEC, credential phishing, malware, invoice/payment fraud). Confirm remediation worked and look for users who clicked before removal.', 'Daily', 'High', 'Email Security > Threat Log > Judgement dropdown (Attacks / Borderline / Spam / All) > + (Filter by) > Remediation Status = Remediated / Marked Safe / No Action Needed > Apply Filters > click a campaign to open Threat Log Details.', true, 21),
  ('ab2', 'Abnormal', 'Account Takeover', 'Investigate Account Takeover (ATO) cases', 'Work open ATO cases. Check suspicious sign-ins, mail rules, and lateral phishing sent from the account. Confirm the response (password reset, session revocation, Duo device review) and close the case with notes.', 'Continuous', 'Critical', 'Email Security > Account Takeover > Cases > filter Case Status / Confidence / Remediation Status > open a case > read the Case Summary and Timeline (Case and Activity tabs) > update the Case Status dropdown or click Remediate.', true, 22),
  ('ab3', 'Abnormal', 'User Reports', 'Triage the Abuse Mailbox / AI Security Mailbox', 'Review user-reported emails and their automated verdicts. Override wrong verdicts. Make sure users get feedback on what they reported, which encourages more reporting.', 'Daily', 'High', 'Email Security > AI Security Mailbox > Analyzed Submissions tab (also check the Not Analyzed tab) > Filter By + > Judgement = Malicious > open the campaign.', true, 23),
  ('ab4', 'Abnormal', 'Campaign Response', 'Use Search & Respond for campaigns', 'When a phish gets through, search for every copy (by sender, subject, URL) and remediate across all mailboxes. Record how many messages were found and removed.', 'As Needed', 'High', 'Email Security > Search & Respond > Message Discovery > Filter By + (sender, subject, date) > Start your search > select messages to remediate.', true, 24),
  ('ab5', 'Abnormal', 'Vendor Risk', 'Monitor Vendor Email Compromise / vendor risk', 'Review vendors flagged as compromised or high-risk. Alert Procurement and Finance, and verify any payment-change requests through a known phone number, never the one in the email.', 'Weekly', 'High', 'Email Security > Vendor Fraud > review each vendor case: Affected Vendor, Description and First Observed.', true, 25),
  ('ab6', 'Abnormal', 'Configuration', 'Maintain the VIP / high-value targets list', 'Keep the VIP list current (President, Provost, CFO, Deans, Finance/Payroll, IT admins) so impersonation detection covers them. Update it after personnel changes.', 'Quarterly', 'Medium', 'Platform > Settings & Configuration', true, 26),
  ('duo1', 'Duo', 'Alert Triage', 'Investigate Duo Risk Assessment Detections', 'When a user marks a push as fraudulent, treat it as a confirmed password compromise. Reset the password, revoke sessions, review recent sign-ins, and check whether the attacker enrolled a new device.', 'Continuous', 'Critical', 'Reports > Authentication Log > expand the filter panel (arrow next to "Last 24 hours") > Risk Assessment Detections > check Risk detections.', true, 27),
  ('duo2', 'Duo', 'Authentication Logs', 'Review denied and anomalous authentications', 'Review the authentication log for repeated denials (possible MFA fatigue / push bombing), logins from unexpected countries or anonymous networks, and odd times. Forward the logs to Splunk so they can be correlated.', 'Daily', 'High', 'Reports > Authentication Log > filter panel > Authentication Result = Access denied > narrow down with Access Denied Reason (Purposely Denied: User Marked Fraud / Blocked: Anonymous IP, Anomalous Push, Frequent Attempts, Locked Out).', true, 28),
  ('duo3', 'Duo', 'Enrollment', 'Alert on new device enrollments followed by suspicious logins', 'Attackers who steal a password often enroll their own phone. Alert on new device enrollment for existing users, especially from unusual locations, and confirm it with the user out-of-band.', 'Daily', 'High', 'Reports > Authentication Log > filter panel > Authentication Result = Enrolled > note the user > clear the filter and search that user, then check for Risk detections or denied results right after they enrolled.', true, 29),
  ('duo4', 'Duo', 'Users', 'Audit bypass users and bypass codes', 'List users in Bypass status and active bypass codes. Every one should have an expiration and a ticket. Remove any that are stale.', 'Weekly', 'High', 'Users > Bypass Codes. The tiles at the top show Total, Weak, Never Expire and Unlimited Reuse codes. Bypass users are under Users > Users > Bypass tile (34 right now).', true, 30),
  ('duo5', 'Duo', 'Users', 'Track unenrolled and inactive users', 'Review the Unenrolled and Inactive user reports. Follow up on unenrolled faculty and staff, and clean up departed users in line with the HR/Registrar offboarding process.', 'Monthly', 'Medium', 'Users > Users > click the Not enrolled tile (6.54k) or the Inactive tile (12.2k) > Export to pull the list.', true, 31),
  ('duo6', 'Duo', 'Audit', 'Review the Duo Administrator log', 'Review admin actions such as policy changes, new admins, role changes, bypass grants, and integration secret-key views. Confirm each matches an approved change.', 'Weekly', 'High', 'Reports > Administrator Actions (filter by date, sort by Administrator/Action).', true, 32),
  ('duo7', 'Duo', 'Coverage', 'Audit application coverage', 'Compare the Duo-protected applications (SSO, VPN, RDP, servers, Banner/admin systems) with the critical app inventory. Make sure no critical system is missing MFA.', 'Quarterly', 'High', 'Applications > Applications > filter by Protection Type and Provisioning > check the Application Policy column, or Export CSV.', true, 33),
  ('x1', 'Cross-Tool', 'Incident Response', 'Maintain playbooks for common incidents', 'Keep written playbooks for phishing, compromised accounts (Duo + Entra + Abnormal), malware/ransomware (CrowdStrike), and data exposure involving FERPA-protected student records. Review them yearly or after major incidents.', 'Annually', 'Critical', null, true, 34),
  ('x2', 'Cross-Tool', 'Documentation', 'Record every investigation in the ticketing system', 'Every alert worked should have a ticket with a timeline, evidence (screenshots, hashes, query links), actions taken, and the final disposition.', 'Continuous', 'High', null, true, 35),
  ('x3', 'Cross-Tool', 'Exercises', 'Run tabletop exercises', 'Run scenario-based tabletops (e.g., a ransomware outbreak during finals week, or BEC aimed at Financial Aid) to test the playbooks and the cross-team communication.', 'Annually', 'Medium', null, true, 36),
  ('x4', 'Cross-Tool', 'Lessons Learned', 'Hold post-incident reviews', 'After every significant incident, hold a blameless review. Update detections, playbooks, and tool configurations based on what you find.', 'As Needed', 'Medium', null, true, 37),
  ('x5', 'Cross-Tool', 'Threat Intel', 'Consume higher-ed threat intel', 'Monitor REN-ISAC, MS-ISAC, and CISA advisories. Turn relevant IOCs and TTPs into CrowdStrike IOCs, Splunk searches, and Defender block-list entries.', 'Weekly', 'Medium', null, true, 38),
  ('x6', 'Cross-Tool', 'Calendar Risk', 'Raise monitoring during academic high-risk periods', 'Phishing aimed at students and staff spikes at semester start, financial aid disbursement, payroll/W-2 season, and enrollment. Plan extra monitoring and awareness messages for those times.', 'As Needed', 'Medium', null, true, 39)
